import { path, ts, TsMorphFileSystemWrapper, tsc } from '@servicenow/sdk-build-core'
import { checkModuleExists } from '@servicenow/sdk-build-plugins'
import type { Project } from '../../project'
import type { IConnector } from '../../connector'
import { createDirIfNotExists } from '../../util'
import { GLIDE_CLIENT_D_TS } from '../../util/ts-glide-client'

/**
 * Main entry point for generating script type definitions
 * Generates glide.*.d.ts and script-includes.*.d.ts files
 */
export async function generateScriptDefinitions(project: Project, connector: IConnector): Promise<void> {
    // Generate the server definitions
    const definitions = await connector.syntaxEditorCompletionDefinitions()

    // Clean up the server definitions
    const { serverDTs, tablesInterface } = cleanTypeDefinitions(definitions)

    const fs = project.getFileSystem()
    const { typesDir } = project.getConfig()
    const typesPath = project.resolvePath(typesDir)

    createDirIfNotExists(typesPath, fs)

    // Write Tables definitions
    if (tablesInterface) {
        fs.writeFileSync(path.join(typesPath, 'tables.modules.d.ts'), tablesInterface)
    }

    fs.writeFileSync(path.join(typesPath, 'glide.server.d.ts'), serverDTs)

    // Write the client definitions
    fs.writeFileSync(path.join(typesPath, 'glide.client.d.ts'), GLIDE_CLIENT_D_TS)

    // Generate script include type definitions
    const scriptIncludeTypes = await createScriptIncludeTypeDefinitions(project, connector)

    if (scriptIncludeTypes) {
        const { standardDeclaration, moduleDeclaration, augmentedModuleDeclaration } = scriptIncludeTypes

        const scriptIncludePath = path.join(typesPath, 'script-includes.server.d.ts')
        fs.writeFileSync(scriptIncludePath, standardDeclaration)

        const moduleScriptIncludePath = path.join(typesPath, 'script-includes.modules.d.ts')
        fs.writeFileSync(moduleScriptIncludePath, moduleDeclaration)

        const augmentedModuleScriptIncludePath = path.join(typesPath, 'augmented-script-includes.modules.d.ts')
        fs.writeFileSync(augmentedModuleScriptIncludePath, augmentedModuleDeclaration)
    }

    project.getLogger().info(`Scripting type definitions generated successfully.`)
}

/**
 * Cleans up ServiceNow server-side type definitions to make them valid TypeScript.
 *
 * This function performs several transformations:
 * 1. Makes all function arguments optional (except variable declarations)
 * 2. Quotes properties with dots in their names
 * 3. Renames reserved words used as parameter names
 * 4. Removes invalid 'static' from constructors
 * 5. Adds type aliases for Java types
 * 6. Extracts Tables interface into separate file
 *
 * @param definitions - Raw type definitions from ServiceNow
 * @returns Cleaned TypeScript definitions and extracted Tables interface
 */
export function cleanTypeDefinitions(definitions: string): { serverDTs: string; tablesInterface?: string } {
    // Make all function arguments optional except variable declarations
    let optionalTypes = definitions.replaceAll(/([,(]\s*)(\w+)(\s*):/g, (value: string) => {
        if (!(value.includes('const ') || value.includes('let ') || value.includes('var '))) {
            return value.replaceAll(':', '?:')
        }
        return value
    })

    // Handle properties with dots in the name, but only if they're not already single or double quoted
    optionalTypes = optionalTypes.replaceAll(/(\w+(?:\.\w+)+)\s*\??:/g, "'$1'?:")

    // Remove delete and function as parameter names since they're reserved words
    optionalTypes = optionalTypes.replaceAll(/\b(delete|function)\??:/g, '$1_?:')

    // Remove static from constructors since it's not valid TS
    optionalTypes = optionalTypes.replaceAll(/static\sconstructor[\s]?/g, 'constructor')

    // Alias some java types that get inserted into the file without any definitions
    let serverDTs = `type ArrayList<T extends unknown = unknown> = T[]
type StringList = string[]
type List<T extends unknown = unknown> = T[]
type TimeZone = string
${optionalTypes}`

    // Extract Tables interface and its referenced types into separate file
    const extraction = extractTablesInterface(serverDTs)
    serverDTs = extraction.serverDTs
    const tablesInterface = extraction.tablesInterface

    // Add reference to tables.modules.d.ts if Tables interface was extracted
    if (tablesInterface) {
        serverDTs = `/// <reference path="./tables.modules.d.ts" />\n\n${serverDTs}`
        return { serverDTs, tablesInterface }
    }

    return { serverDTs }
}

function extractTablesInterface(serverDTs: string): {
    serverDTs: string
    tablesInterface?: string
} {
    const sourceFile = tsc.createSourceFile('temp.d.ts', serverDTs, tsc.ScriptTarget.Latest, true)
    const tablesInterface = sourceFile.statements.find(
        (stmt): stmt is tsc.InterfaceDeclaration => tsc.isInterfaceDeclaration(stmt) && stmt.name.text === 'Tables'
    )
    if (!tablesInterface) {
        return { serverDTs }
    }

    const referencedTypes = new Set<string>()
    for (const member of tablesInterface.members) {
        if (tsc.isPropertySignature(member) && member.type) {
            collectTypeReferences(member.type, referencedTypes)
        }
    }

    const typeNodesToExtract = new Set<tsc.Node>()
    const processedTypes = new Set<string>()
    const extractTypeAndBases = (typeName: string) => {
        if (processedTypes.has(typeName)) {
            return
        }
        processedTypes.add(typeName)
        const typeDecl = sourceFile.statements.find(
            (stmt): stmt is tsc.InterfaceDeclaration | tsc.TypeAliasDeclaration | tsc.ClassDeclaration =>
                (tsc.isInterfaceDeclaration(stmt) ||
                    tsc.isTypeAliasDeclaration(stmt) ||
                    tsc.isClassDeclaration(stmt)) &&
                stmt.name?.text === typeName
        )

        if (typeDecl) {
            typeNodesToExtract.add(typeDecl)
            // Extract base table interface if necessary
            if (tsc.isInterfaceDeclaration(typeDecl) && typeDecl.heritageClauses) {
                for (const heritage of typeDecl.heritageClauses) {
                    if (heritage.token === tsc.SyntaxKind.ExtendsKeyword) {
                        for (const type of heritage.types) {
                            if (tsc.isIdentifier(type.expression)) {
                                extractTypeAndBases(type.expression.text)
                            }
                        }
                    }
                }
            }
        }
    }

    for (const typeName of referencedTypes) {
        extractTypeAndBases(typeName)
    }

    // Remove declare keyword
    const printer = tsc.createPrinter({ newLine: tsc.NewLineKind.LineFeed })
    const extractedTypesStr = Array.from(typeNodesToExtract)
        .map((node) => {
            let text = printer.printNode(tsc.EmitHint.Unspecified, node as tsc.Node, sourceFile)
            text = text.replace(/^\s*declare\s+/, '')
            return text
        })
        .join('\n\n')
    let tablesInterfaceStr = printer.printNode(tsc.EmitHint.Unspecified, tablesInterface, sourceFile)
    tablesInterfaceStr = tablesInterfaceStr.replace(/^\s*declare\s+/, '')

    // Build the final tables module with declare global wrapper and remove extracted interfaces from source
    const tablesModule = `export {}\n\n${extractedTypesStr ? `${extractedTypesStr}\n\n` : ''}declare global {\n${tablesInterfaceStr}\n}\n`
    const nodesToRemove = new Set([tablesInterface, ...typeNodesToExtract])
    const remainingStatements = sourceFile.statements.filter((stmt) => !nodesToRemove.has(stmt))
    const modifiedServerDTs = tsc.factory.updateSourceFile(sourceFile, remainingStatements)

    return { serverDTs: printer.printFile(modifiedServerDTs), tablesInterface: tablesModule }
}

function collectTypeReferences(typeNode: tsc.TypeNode, references: Set<string>): void {
    if (tsc.isTypeReferenceNode(typeNode)) {
        if (tsc.isIdentifier(typeNode.typeName)) {
            references.add(typeNode.typeName.text)
        }
    } else if (tsc.isTypeLiteralNode(typeNode)) {
        for (const member of typeNode.members) {
            if (tsc.isPropertySignature(member) && member.type) {
                collectTypeReferences(member.type, references)
            }
        }
    } else if (tsc.isUnionTypeNode(typeNode) || tsc.isIntersectionTypeNode(typeNode)) {
        for (const type of typeNode.types) {
            collectTypeReferences(type, references)
        }
    } else if (tsc.isArrayTypeNode(typeNode)) {
        collectTypeReferences(typeNode.elementType, references)
    }
}

enum DeclarationCategory {
    NOW = 'now',
    MODULE = 'module',
    CONFLICTING_MODULE = 'conflicting-module',
}
type ScriptInfo = { id: string; script: string; name: string | undefined }

async function hasConflictWithGlideModule(namespace: string, project: Project): Promise<boolean> {
    const module = namespace.split('.')[0]
    return checkModuleExists(
        `@servicenow/glide/${module}`,
        project.getLogger(),
        project.getFileSystem(),
        project.getRootDir()
    )
}

export async function createScriptIncludeTypeDefinitions(
    project: Project,
    connector: IConnector
): Promise<{ standardDeclaration: string; moduleDeclaration: string; augmentedModuleDeclaration: string } | undefined> {
    const { scope } = project.getConfig()
    const logger = project.getLogger()
    const scriptIncludeRegistry = await connector.syntaxEditorCacheScriptIncludes()
    const { referencesInNowIncludes, referencesInModules } = resolveScriptIncludeReferences(
        project,
        scriptIncludeRegistry
    )

    const resolvedScriptIncludes = Array.from(referencesInNowIncludes.values()).reduce((acc, reference) => {
        const candidates = reference.includes('.')
            ? [reference]
            : [reference, `${scope}.${reference}`, `global.${reference}`]

        for (const candidate of candidates) {
            const includeId = scriptIncludeRegistry[candidate]
            if (includeId) {
                acc.set(includeId, { name: candidate, id: includeId })
                break
            }
        }

        return acc
    }, new Map<string, { name: string; id: string }>())

    Object.keys(scriptIncludeRegistry)
        .filter((apiName) => apiName.includes('.') && !apiName.includes(' '))
        .forEach((apiName) => {
            const apiPrefix = apiName.split('.')[0]
            if (apiPrefix && referencesInModules.has(apiPrefix)) {
                const includeId = scriptIncludeRegistry[apiName]
                if (includeId) {
                    resolvedScriptIncludes.set(includeId, { name: apiName, id: includeId })
                }
            }
        })

    logger.debug(
        `Found script includes: ${Array.from(resolvedScriptIncludes.values())
            .map((i) => i.name)
            .join(', ')}`
    )

    if (resolvedScriptIncludes.size === 0) {
        //No script includes found
        logger.info(`No script includes references found in the project.`)
        return undefined
    }

    logger.info(`Fetching script include definitions from the server.`)
    const scriptDefinitions = await connector.syntaxEditorDefinitionsScriptIncludes(
        Array.from(resolvedScriptIncludes.keys())
    )
    const scriptResults = Object.entries(scriptDefinitions).map(([id, scriptDef]) => {
        // biome-ignore lint/style/noNonNullAssertion: we only get scripts for the ids already present in resolvedScriptIncludes
        const resolvedInclude = resolvedScriptIncludes.get(id)!

        if (!scriptDef) {
            scriptDef = `declare const ${resolvedInclude.name.split('.').pop()}: any`
        }

        return {
            id,
            script: scriptDef,
            name: resolvedInclude.name,
        }
    })

    if (scriptResults.length < 1) {
        logger.info(`No script include definitions found on the server.`)
        return undefined
    }

    const nowIncludeGroups: Record<string, ScriptInfo[]> = {}
    const moduleGroups: Record<string, ScriptInfo[]> = {}
    const conflictingModuleGroups: Record<string, ScriptInfo[]> = {}

    for (const scriptInfo of scriptResults) {
        const [name] = scriptInfo.name.split('.')
        if (name) {
            const addToGroup = (group: Record<string, ScriptInfo[]>, name: string) => {
                if (!group[name]) {
                    group[name] = []
                }
                group[name].push(scriptInfo)
            }

            if (referencesInNowIncludes.has(scriptInfo.name)) {
                addToGroup(nowIncludeGroups, name)
            }

            const modulePrefix = scriptInfo.name.split('.')[0]
            if (modulePrefix && referencesInModules.has(modulePrefix)) {
                const hasConflict = await hasConflictWithGlideModule(scriptInfo.name, project)
                if (hasConflict) {
                    addToGroup(conflictingModuleGroups, name)
                } else {
                    addToGroup(moduleGroups, name)
                }
            }
        }
    }

    logger.info(`Generating type declarations for script includes.`)
    const nowIncludeContent = generateTypeDeclarations(nowIncludeGroups, scope, DeclarationCategory.NOW)
    const moduleIncludeContent = generateTypeDeclarations(moduleGroups, scope, DeclarationCategory.MODULE)
    const conflictingModuleContent = generateTypeDeclarations(
        conflictingModuleGroups,
        scope,
        DeclarationCategory.CONFLICTING_MODULE
    )

    return {
        standardDeclaration: nowIncludeContent,
        moduleDeclaration: moduleIncludeContent,
        augmentedModuleDeclaration: conflictingModuleContent,
    }
}

export function extractReferencesFromSourceFile(
    file: ts.SourceFile,
    scriptIncludeRegistry: Record<string, string>,
    scope: string
) {
    return file
        .getDescendants()
        .map((node) => {
            const propertyAccessExp = node.asKind(ts.SyntaxKind.PropertyAccessExpression)
            if (propertyAccessExp) {
                const text = propertyAccessExp.getText()
                if (scriptIncludeRegistry[text]) {
                    return text
                }

                const apiName = `${scope}.${propertyAccessExp.getExpression().getText()}`
                if (scriptIncludeRegistry[apiName]) {
                    return apiName
                }

                return undefined
            }

            const callExp = node.asKind(ts.SyntaxKind.CallExpression)
            if (callExp) {
                const name = callExp.getExpression().getText()
                const apiName = `${scope}.${name}`
                return scriptIncludeRegistry[apiName] ? apiName : undefined
            }

            const newExp = node.asKind(ts.SyntaxKind.NewExpression)
            if (newExp) {
                const name = newExp.getExpression().getText()
                const apiName = `${scope}.${name}`
                return scriptIncludeRegistry[apiName] ? apiName : undefined
            }

            return undefined
        })
        .filter((ns) => ns !== undefined)
}

function resolveScriptIncludeReferences(
    project: Project,
    scriptIncludeRegistry: Record<string, string>
): {
    referencesInNowIncludes: Set<string>
    referencesInModules: Set<string>
} {
    const fs = project.getFileSystem()
    const workingDir = project.getRootDir()

    const {
        fluentDir,
        serverModulesDir,
        serverModulesExcludePatterns: excludePatterns,
        serverModulesIncludePatterns: includePatterns,
    } = project.getConfig()
    const logger = project.getLogger()
    const { scope } = project.getConfig()

    const fsWrapper = new TsMorphFileSystemWrapper(fs)
    const proj = new ts.Project({
        fileSystem: fsWrapper,
        compilerOptions: {
            allowJs: true,
        },
    })

    const nowIncludeFilesGlobPattern = path.normalize(path.join(workingDir, `${fluentDir}/**/*.js`))
    const modulesDir = path.normalize(path.join(workingDir, serverModulesDir))

    logger.info(`Searching files for script include usages at path: ${nowIncludeFilesGlobPattern}`)

    const addedFiles = proj.addSourceFilesAtPaths(nowIncludeFilesGlobPattern)

    logger.debug(`Found ${addedFiles.length} javascript files to inspect`)

    const referencesInNowIncludes = new Set<string>()

    addedFiles.forEach((file) => {
        logger.debug(`inspecting script file: ${file.compilerNode.fileName}`)

        const references = extractReferencesFromSourceFile(file, scriptIncludeRegistry, scope)

        logger.debug(`found expressions in ${file.getFilePath()}: ${references.join(', ')}`)

        references.forEach((ns) => referencesInNowIncludes.add(ns))
    })

    const excludedFiles = new Set<string>()
    if (excludePatterns && excludePatterns.length > 0) {
        const excluded = fsWrapper.globSync(excludePatterns, { cwd: modulesDir })
        excluded.forEach((file) => excludedFiles.add(path.resolve(file)))
    }

    const moduleFiles = [] as ts.SourceFile[]
    const includedFiles = fsWrapper.globSync(includePatterns, { cwd: modulesDir })
    includedFiles.forEach((file) => {
        if (!excludedFiles.has(file)) {
            moduleFiles.push(proj.addSourceFileAtPath(file))
        }
    })

    const referencesInModules = new Set<string>()

    if (moduleFiles.length > 0) {
        moduleFiles.forEach((file) => {
            file.getDescendantsOfKind(ts.SyntaxKind.ImportDeclaration).forEach((importDecl) => {
                const moduleSpecifier = importDecl.getModuleSpecifier()
                if (moduleSpecifier?.getLiteralValue().match(/^@servicenow\/glide\/\w+/)) {
                    const scope = moduleSpecifier.getLiteralValue().split('/').pop()
                    if (scope) {
                        referencesInModules.add(scope)
                    }
                }
            })
        })
    }

    return {
        referencesInModules,
        referencesInNowIncludes,
    }
}

function generateTypeDeclarations(groups: Record<string, ScriptInfo[]>, scope: string, type: DeclarationCategory) {
    const project = new ts.Project({ useInMemoryFileSystem: true })
    const getPrefix = (group: string, type: DeclarationCategory) => {
        switch (type) {
            case DeclarationCategory.NOW:
                return `declare namespace ${group} {\n`
            case DeclarationCategory.MODULE:
                return `declare module '@servicenow/glide/${group}' {\n ${group === 'global' ? ' namespace global {\n' : ''}`
            case DeclarationCategory.CONFLICTING_MODULE:
                return `import '@servicenow/glide/${group}'\n declare module '@servicenow/glide/${group}' {\n`
        }
    }
    const getSuffix = (group: string, type: DeclarationCategory) => {
        switch (type) {
            case DeclarationCategory.NOW:
            case DeclarationCategory.CONFLICTING_MODULE:
                return `}\n`
            case DeclarationCategory.MODULE:
                return `}\n ${group === 'global' ? '}\n' : ''}`
        }
    }

    return Object.entries(groups).reduce((acc, [group, scriptIncludes]) => {
        const sameScope = group === scope

        let script = sameScope ? '' : getPrefix(group, type)
        script += scriptIncludes.map((scriptInclude) => scriptInclude.script).join('\n\n')
        script += sameScope ? '' : getSuffix(group, type)

        const scriptIncludeDeclaration = project.createSourceFile('script-include.d.ts', script, { overwrite: true })
        const scriptIncludeDeclarationStruct = scriptIncludeDeclaration.getStructure()

        const fixClassDeclaration = (structure: ts.Structures) => {
            ts.forEachStructureChild(structure, fixClassDeclaration)
            if (ts.Structure.isClass(structure)) {
                structure.hasDeclareKeyword = false
                structure.methods?.forEach((method) => {
                    method.parameters?.forEach((param) => {
                        param.hasQuestionToken = true
                    })
                })
                if (group === 'global' && structure.name === 'Attachment') {
                    structure.methods?.pop()
                }
            }

            if (ts.Structure.isVariableStatement(structure)) {
                structure.hasDeclareKeyword = false
            }
        }

        fixClassDeclaration(scriptIncludeDeclarationStruct)
        const updatedDeclaration = project.createSourceFile(
            'updated-script-include.d.ts',
            scriptIncludeDeclarationStruct,
            { overwrite: true }
        )

        acc += `${updatedDeclaration.getText(true)}\n`
        project.removeSourceFile(scriptIncludeDeclaration)
        project.removeSourceFile(updatedDeclaration)

        return acc
    }, '')
}
